from pages import L,IG,FB,ADS
from pages5 import mk
from pages7 import SEND
from pages8 import ind,BEFORE,DIRS
def notice(slug,plat,text,title,mean,answer,steps,faqs):
    return mk(slug,title,f'“{text}” notice',f'What the {plat} notice “{text}” means, what to do in the first hour, and which official link to use. Updated November 2026.',
     f'“{text}”: what this {plat} notice means',f'You saw this exact message. Here is what it usually means and what to do next.',answer,
     [('Screenshot','Keep the notice and date.'),('One appeal','Plain words, once.'),('No new accounts','Wait for the decision.')],
     f'<h2 id="meaning">What it usually means</h2><p>{mean}</p><h2 id="first-hour">The first hour</h2><ol>'+''.join(f'<li>{s}</li>' for s in steps)+'</ol>',
     [('ig','Official links',(IG if plat=='Instagram' else FB)[:4])],[BEFORE,SEND],DIRS+', '+L('instagram-notice-types','Instagram notice types')+', '+L('facebook-notice-types','Facebook notice types')+'.',faqs)
PAGES=[
notice('instagram-we-suspended-your-account-notice','Instagram','We suspended your account','“We Suspended Your Account” on Instagram: What It Means (2026)','Instagram has paused the account because it believes the account or its activity broke a rule. The notice usually shows a date by which you can disagree. Until then, the account is hidden from others.','<strong>“We suspended your account” means Instagram paused the account and is giving you a window to disagree.</strong> Tap the option to disagree on the notice, complete any video selfie, and write one short factual appeal. If you do nothing before the date shown, the account can be permanently disabled. Instagram makes the final decision.',['Screenshot the notice, including the date.','Tap the disagree option on the notice.','Complete any video selfie or ID check it asks for.','Write a short factual appeal, once.'],[('How long do I have?','The notice shows the date. Meta states that users generally have 180 days to appeal a suspension.'),('Can others see my profile while suspended?','Usually not. The account is hidden while suspended.'),('I emailed my appeal letter to Meta. Did it arrive?','Meta does not process account appeals by email. Use the disagree option on the notice.')]),
notice('instagram-your-account-has-been-disabled-notice','Instagram','Your account has been disabled','“Your Account Has Been Disabled” on Instagram: What to Do (2026)','Instagram disabled the account for a rule it names, or for not following its terms. If a review option still shows, the decision can be appealed. If it says the decision cannot be reversed, the in-app route is closed.','<strong>“Your account has been disabled” means Instagram removed access to the account.</strong> If the notice offers a review or disagree option, use it once and complete any check it asks for. If no option shows, see the no-appeal-button guide and the official links directory. Instagram makes the final decision.',['Screenshot the notice.','Look for a review or disagree option and use it once.','If no option shows, open the no-appeal-button guide.','Do not open new accounts on the same device.'],[('Is disabled the same as suspended?','Not quite. A suspension usually has an appeal window. Disabled can follow a suspension or come directly.'),('Can I get my content back?','Sometimes Meta lets you download your data. Look for that option on the notice.')]),
notice('facebook-we-suspended-your-account-notice','Facebook','We suspended your account','“We Suspended Your Account” on Facebook: What It Means (2026)','Facebook paused the account and shows a date by which you can disagree. If the account was used by someone else, say so in the appeal.','<strong>“We suspended your account” on Facebook means the account is paused and you have a window to disagree.</strong> Use the disagree option on the notice, finish any ID or video selfie step, and appeal once in plain words. If a hacker caused it, start at facebook.com/hacked. Meta makes the final decision.',['Screenshot the notice.','Choose the disagree option.','Upload ID or record a video selfie if asked.','Appeal once.'],[('How long do I have to appeal?','The notice shows a date. Meta states that users generally have 180 days.'),('Can I still use Messenger?','Usually not while the Facebook account is suspended.')]),
notice('instagram-help-us-confirm-its-you-notice','Instagram','Help us confirm it’s you','“Help Us Confirm It’s You” on Instagram: What to Do (2026)','Instagram wants to check that a real person owns the account, often after unusual activity. It usually asks for a video selfie or a code sent to your email or phone.','<strong>“Help us confirm it’s you” is an identity check, not a ban.</strong> Complete the code or video selfie on the device you normally use, in good light, without a VPN. If it fails, wait before trying again rather than repeating it many times. Instagram makes the final decision.',['Use the device and network you normally use.','Enter the code or record the video selfie slowly.','If it fails, wait before retrying.','Check your email for messages from security@mail.instagram.com only.'],[('Is this check a ban?','No. It is a security check. Failing it repeatedly can lead to a suspension.'),('The selfie keeps looping. What now?','See the selfie looping guide, and wait before retrying.')]),
ind('church-and-faith-organization-facebook-page-disabled','Churches and faith organizations','Facebook Page','Church Facebook Page or Instagram Disabled: What to Do (2026)','<strong>For a church or faith organization, check whether the Page, an admin profile or the ad account is restricted.</strong> Hacked volunteer admins and donation-style posts are common triggers. Recover the admin first, remove unknown admins, then request one review. Meta makes the final decision.',['A hacked volunteer admin profile posting scams.','Donation requests that look like fundraising scams.','Livestreams flagged for copyrighted music.','Impersonating pages asking members for money.'],[('A fake page asks our members for money. What do we do?','Report it as impersonation and warn members from your real Page.'),('Our livestream was removed for music. Does that affect the Page?','Repeated copyright removals can restrict a Page.')]),
ind('school-and-tutoring-business-instagram-disabled','Schools and tutoring businesses','Instagram','School or Tutoring Instagram Disabled: What to Do (2026)','<strong>For a school or tutoring business, check whether the account is disabled or only some features are limited.</strong> Posts with children and shared staff logins are common risks. Appeal once from the notice and keep at least two trusted admins. Meta makes the final decision.',['Photos of children without clear context.','Shared staff logins from many devices.','Ads aimed at teenagers.','Giveaway posts that look like spam.'],[('Several teachers post from one login. Is that okay?','It raises security checks. Use roles where possible.'),('Can we appeal on behalf of the school?','The appeal comes from the account notice, by whoever can log in.')]),
ind('wedding-and-event-business-instagram-disabled','Wedding and event businesses','Instagram','Wedding or Event Business Instagram Disabled: What to Do (2026)','<strong>For a wedding or event business, check the notice first: a disabled account, a restricted ad account, or a hacked login need different routes.</strong> Copyrighted music in reels and fake vendor pages are common. Appeal once and keep proof of your business. Meta makes the final decision.',['Copyrighted music in reels.','Impersonating vendor pages.','Hacked logins used for fake promotions.','Repeated reposting of client photos.'],[('A reel was removed for music. Is my account at risk?','Repeated copyright removals can lead to restrictions.'),('Someone copied our page. What do we do?','Report it as impersonation and keep screenshots.')]),
ind('bar-and-nightclub-instagram-facebook-disabled','Bars and nightclubs','Instagram','Bar or Nightclub Instagram or Ads Restricted: What to Do (2026)','<strong>For a bar or nightclub, alcohol ads have extra rules on age targeting and claims.</strong> Check whether the account, the Page or the ad account is restricted, fix the flagged item, then request one review. Meta makes the final decision.',['Alcohol ads without age limits.','Event promotions that look like giveaways.','Copyrighted music in reels.','Shared logins among promoters.'],[('Can bars run alcohol ads?','Yes, within Meta’s rules on age and local law.'),('Our promoters use one login. Is that a risk?','Yes. Give each person their own role.')]),
ind('home-services-contractor-facebook-page-restricted','Contractors and home services','Facebook Page','Contractor Facebook Page or Ads Restricted: What to Do (2026)','<strong>For a contractor or home services business, check Business Support Home to see what is restricted.</strong> Lead ads with misleading claims and reviews from hacked profiles are common triggers. Fix the item, then request one review. Meta makes the final decision.',['Lead forms with before-and-after claims.','Financing offers in ads.','Hacked admin profile posting spam.','Several ad accounts created at once.'],[('Our lead ads were rejected. What first?','Read the rejection reason and fix the ad or landing page before requesting a review.'),('Can we run financing offers?','Credit offers fall under Special Ad Categories with targeting limits.')]),
]
